// Fixed-point tables of the Marbles port (generated by scripts/gen_tables.py
// into tables_fx.cc from upstream's float tables). All of them are plain
// const data: link-time constants, no run-time initialisation.

#ifndef OP1MARBLES_FX_TABLES_FX_H_
#define OP1MARBLES_FX_TABLES_FX_H_

#include <stdint.h>

#include "src/fx.h"

namespace op1marbles {
namespace fx {

const int kMaxDegrees = 16;

struct DegreeFx {
  int32_t voltage;  // Q16 volts
  uint8_t weight;
};

struct ScaleFx {
  int32_t base_interval;  // Q16 volts
  int32_t num_degrees;
  DegreeFx degree[kMaxDegrees];
};

// Beta inverse CDFs, Q31: 60 pointers (6 bias rows x 10 spread columns, as
// upstream's distributions_table), each 3 x 129 values.
extern const uint32_t* const distributions_table[60];
extern const uint32_t dist_icdf_4_3[387];
extern const uint32_t lut_raised_cosine[257];    // Q31
extern const uint32_t lut_logit_threshold[257];  // u < p  <=>  u <= threshold
extern const uint32_t lut_exp2_q30[257];
extern const ScaleFx preset_scales[6];

extern const uint32_t k005fQ32;
extern const uint32_t k095fQ32;
extern const uint32_t kMaxRampQ32;
extern const uint32_t k099999fQ32;

}  // namespace fx
}  // namespace op1marbles

#endif  // OP1MARBLES_FX_TABLES_FX_H_
